// loaded state has an empty BaseCommit (left over from a concurrent warning
// that wrote partial state). The caller falls through to initializeSession
// to repair it.
var errPartialState = errors.New("partial session state")

// HandleTurnEnd dispatches strategy-specific actions emitted when an agent turn ends.
// The primary job is to finalize all checkpoints from this turn with the full transcript.
//
// During a turn, PostCommit writes provisional transcript data (whatever was available
// at commit time). HandleTurnEnd replaces that with the complete session transcript
// (from prompt to stop event), ensuring every checkpoint has the full context.
// finalizeDeadline bounds that rewrite's network phase so the hook finishes
// before its host kills it; the zero time means no deadline.
func (s *ManualCommitStrategy) HandleTurnEnd(ctx context.Context, state *SessionState, finalizeDeadline time.Time) error { //nolint:unparam // error return is part of the hook contract; callers check it
	hadMidTurnCommits := len(state.TurnCheckpointIDs) > 0

	// Finalize all checkpoints from this turn with the full transcript.
	//
	// IMPORTANT: This is best-effort - errors are logged but don't fail the hook.
	// Failing here would prevent session cleanup and could leave state inconsistent.
	// The provisional transcript from PostCommit is already persisted, so the
	// checkpoint isn't lost - it just won't have the complete transcript.
	errCount := s.finalizeAllTurnCheckpoints(ctx, state, finalizeDeadline)
	if errCount > 0 {
		logCtx := logging.WithComponent(ctx, "checkpoint")
		logging.Warn(logCtx, "HandleTurnEnd completed with errors (best-effort)",
			slog.String("session_id", state.SessionID),
			slog.Int("error_count", errCount),
		)
	}

	// Advance CheckpointTranscriptStart to the actual transcript end after
	// mid-turn commits. When an agent commits mid-turn (e.g., Codex "commit/push"),
	// condensation records TotalTranscriptLines at commit time, but the agent
	// continues writing to the transcript (tool results, token counts, task_complete).
	// Without this fix, the next checkpoint's scoped transcript starts mid-turn,
	// including a tail of already-condensed content.
	//
	// Skip this when carry-forward is active. carryForwardRemainingFiles
	// intentionally resets CheckpointTranscriptStart to 0 so the next checkpoint
	// remains self-contained with the full transcript.
	if hadMidTurnCommits && state.TranscriptPath != "" && len(state.FilesTouched) == 0 {
		advanceCheckpointTranscriptStartToTurnEnd(ctx, state)
	}

	return nil
}

// advanceCheckpointTranscriptStartToTurnEnd moves CheckpointTranscriptStart to
// the current transcript end after a fully-condensed turn (see HandleTurnEnd's
// call-site comment). When the advance cannot run for a late-transcript agent
// — agy flushes its transcript only after Stop, so this read routinely races
// the flush and sees the pre-turn state — the failure is recorded in
// TranscriptOffsetPending so the next mid-turn condensation can retry against
// the by-then-flushed file (resolvePendingTranscriptOffset). Without the
// retry, a lost race leaves the offset inside the previous turn, so the next
// checkpoint's prompt extraction picks up the previous turn's prompt and its
// scoped transcript includes an already-condensed tail. Streaming-transcript
// agents never set the flag: for them a non-growing transcript legitimately
// means "no new content".
func advanceCheckpointTranscriptStartToTurnEnd(ctx context.Context, state *SessionState) {
	logCtx := logging.WithComponent(ctx, "hooks")
	ag, agErr := agent.GetByAgentType(state.AgentType)
	if agErr != nil {
		return
	}
	_, isLate := agent.AsLateTranscriptWriter(ag)

	advanced := false
	if transcriptPath, resolveErr := resolveTranscriptPath(state); resolveErr == nil {
		if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
			if pos, posErr := analyzer.GetTranscriptPosition(transcriptPath); posErr == nil && pos > state.CheckpointTranscriptStart {
				logging.Debug(logCtx,
					"advancing CheckpointTranscriptStart to turn end after mid-turn commit",
					slog.String("session_id", state.SessionID),
					slog.Int("old_offset", state.CheckpointTranscriptStart),
-----
// that can wait on a slow remote; the zero time means no deadline.
//
// Returns the number of errors encountered (best-effort: continues processing on error).
// Checkpoints the deadline or a cancellation cut off are not counted: the
// interruption is logged and recorded as capture degradation instead.
func (s *ManualCommitStrategy) finalizeAllTurnCheckpoints(ctx context.Context, state *SessionState, deadline time.Time) int {
	if len(state.TurnCheckpointIDs) == 0 {
		return 0 // No mid-turn commits to finalize
	}

	logCtx := logging.WithComponent(ctx, "checkpoint")

	logging.Info(logCtx, "finalizing turn checkpoints with full transcript",
		slog.String("session_id", state.SessionID),
		slog.Int("checkpoint_count", len(state.TurnCheckpointIDs)),
	)

	if ctx.Err() != nil {
		abandonInterruptedFinalize(logCtx, state, ctx.Err())
		return 0
	}

	// Read full transcript from live transcript file, re-resolving the path if the
	// agent relocated it mid-session (e.g., Cursor CLI flat → nested layout change).
	if state.TranscriptPath == "" {
		logging.Warn(logCtx, "finalize: no transcript path, skipping",
			slog.String("session_id", state.SessionID),
		)
		state.TurnCheckpointIDs = nil
		return 1 // Count as error - all checkpoints will be skipped
	}

	transcriptPath, resolveErr := resolveTranscriptPath(state)
	if resolveErr != nil {
		logging.Warn(logCtx, "finalize: transcript path resolution failed, skipping",
			slog.String("session_id", state.SessionID),
			slog.Any("error", resolveErr),
		)
		state.TurnCheckpointIDs = nil
		return 1 // Count as error - all checkpoints will be skipped
	}

	ag, _ := agent.GetByAgentType(state.AgentType) //nolint:errcheck // ag may be nil for unknown agent types; ExtractSkillEvents handles nil

	fullTranscript, err := agent.ReadTranscriptFile(transcriptPath)
	if err != nil || len(fullTranscript) == 0 {
		// A late-transcript agent (agy) writes its transcript AFTER the Stop
		// hook, so an empty file here is the placeholder PrepareTranscript
		// materialised when the flush lost the race — a normal, transient
		// state, not a lost transcript. Keep TurnCheckpointIDs so a later
		// HandleTurnEnd in this turn finalizes with the flushed content, the
		// same deferral the degraded-scanner path below uses; nilling them
		// would abandon the backfill for every mid-turn checkpoint of the turn
		// on the first Stop that beat the flush.
		if _, late := agent.AsLateTranscriptWriter(ag); late && err == nil {
			logging.Info(logCtx, "finalize: late-transcript agent has not flushed yet, deferring",
				slog.String("session_id", state.SessionID),
				slog.String("transcript_path", state.TranscriptPath),
				slog.Int("checkpoint_count", len(state.TurnCheckpointIDs)),
			)
			return 1 // Reported, not abandoned: TurnCheckpointIDs survive for the retry
		}
		msg := "finalize: empty transcript, skipping"
		if err != nil {
			msg = "finalize: failed to read transcript, skipping"
		}
		logging.Warn(logCtx, msg,
			slog.String("session_id", state.SessionID),
			slog.String("transcript_path", state.TranscriptPath),
			slog.Any("error", err),
		)
		state.TurnCheckpointIDs = nil
		return 1 // Count as error - all checkpoints will be skipped
	}

	// Open repository (needed for the checkpoint store)
	repo, err := OpenRepository(ctx)
	if err != nil {
		if ctx.Err() != nil {
			abandonInterruptedFinalize(logCtx, state, ctx.Err())
			return 0
		}
		logging.Warn(logCtx, "finalize: failed to open repository",
			slog.String("error", err.Error()),
		)
		state.TurnCheckpointIDs = nil
		return 1 // Count as error - all checkpoints will be skipped
	}
	defer repo.Close()

	prompts := readPromptsFromFilesystem(ctx, state.SessionID)

	// Persist newly extracted events into state (the caller's MutateSessionState
	// saves them); telemetry for them is emitted by the lifecycle turn-end
	// handler, which snapshots state.SkillEvents growth around HandleTurnEnd.
	_, skillEvents := persistNewSkillEvents(state, agent.ExtractSkillEvents(ctx, ag, fullTranscript, 0))

	// Sanitize before externalizing and redacting, matching CondenseSession's
	// sanitize -> externalize -> redact order. Skill events above are extracted from
	// the pre-sanitization bytes because they are session telemetry rather than
	// stored transcript content.
	fullTranscript = agent.SanitizeTranscriptForStorage(ag, fullTranscript)

	// Redact secrets before writing. Checkpoint store methods require
	// pre-redacted in-memory transcript content from callers. The live
	// transcript on disk is still treated as raw/untrusted input, so redact it
	// here before anything is persisted to the metadata branch.
	//
	// On failure: drop the transcript but continue writing checkpoint metadata
	// (files touched, prompts). Hooks run without user interaction
	// so there is no retry path — preserving partial metadata is better than
	// losing everything. Persisting an unredacted transcript would be worse.
	// Run the regex-only pipeline over the transcript — OPF runs later in
	// the pre-push rewrite path, which re-redacts these regex-only blobs
	// and produces OPF-applied (9-layer) commits before the push goes out.
	// Externalize inline images BEFORE redaction, mirroring CondenseSession, so the
	// finalized (authoritative, full-session) transcript keeps its placeholders and
	// matching assets instead of re-inlining what condensation lifted out. Opt-in;
	// a no-codec agent or a transcript with no images is a no-op.
	var finalizeAssets []checkpoint.TranscriptAsset
	// Whether externalization actually RAN at finalize. When it did not (flag
	// off here even though it may have been on at condensation — e.g. an
	// ENTIRE_EXTERNALIZE_IMAGES env override not inherited by the hook
	// process, or settings toggled mid-session), an empty finalizeAssets means
	// "extraction didn't run", NOT "the transcript has no images" — clearing
	// the previously-stored assets would permanently lose them (the re-inlined
	// base64 is destroyed by redaction below).
	externalizationRan := false
	if settings.IsImageExternalizationEnabled(ctx) {
		rewritten, assets, exErr := extractSessionImages(state.AgentType, fullTranscript)
		if exErr != nil {
			logging.Warn(logCtx, "finalize: image externalization failed; leaving transcript inline",
				slog.String("session_id", state.SessionID),
				slog.String("error", exErr.Error()),
			)
		} else {
			fullTranscript = rewritten
			finalizeAssets = assets
			externalizationRan = true
		}
	}
	// Re-capture sidecar images (e.g. Cursor's SQLite store) so a finalize that
	// rewrites the transcript re-writes them too. When the full transcript differs
	// from the stored (mid-turn) one, writeAssets clears the whole assets/ folder
	// and re-writes only these assets — omitting the sidecar images here would drop
	// what CondenseSession captured. Content-hash names make this idempotent with
	// condensation's write; when the transcript is unchanged, writeAssets is not
	// called and condensation's assets are left intact.
	finalizeAssets = append(finalizeAssets, sidecarSessionImages(ctx, logCtx, ag, state)...)
	// Sidecar capture is best-effort: a transient miss here (sqlite3 locked/timed
	// out) yields no assets. For a sidecar-capable agent, preserve the assets a
	// prior condensation stored rather than letting an empty set clear them.
	_, sidecarCapable := agent.AsSidecarImageProvider(ag)

	redactedTranscript, redactOK := redactFinalizedTranscript(logCtx, repo, state.SessionID, fullTranscript)
	if !redactOK {
		return 1
	}

	// Post-commit emits regex-only blobs; the writer joins + redacts
	// via checkpoint.redactedJoinedPrompts. OPF runs later, once per
	// push, in the pre-push rewrite path.
	// The hook store envelope (see hookCheckpointStoreOptions): the transcript
	// finalize targets existing checkpoints whose refs — and, on a partial
	// clone, whose blobs — may live only on the remote (resumed/adopted
	// multi-machine sessions). This loops over every checkpoint of the turn
	// against one store, so both fetch paths need their own memo or a dead
	// network costs the budget N times: gitRefsStore.fetchFailure covers refs,
	// and hookBlobFetcher memoizes an exhausted blob fetch. Neither memo detects
	// a slow remote whose fetches succeed just under budget, so the turn-end
	// deadline bounds this network phase as a whole. Only this phase checks it:
	// the preparation above is local work, and the deadline exists to stop slow
	// fetches.
	networkCtx := ctx
	if !deadline.IsZero() {
		var cancel context.CancelFunc
		networkCtx, cancel = context.WithDeadline(ctx, deadline)
		defer cancel()
	}
	if networkCtx.Err() != nil {
		abandonInterruptedFinalize(logCtx, state, networkCtx.Err())
		return 0
	}
	stores, err := checkpoint.Open(networkCtx, repo, s.hookCheckpointStoreOptions(networkCtx))
	if err != nil {
		if networkCtx.Err() != nil {
			abandonInterruptedFinalize(logCtx, state, networkCtx.Err())
			return 0
		}
		logging.Warn(logCtx, "finalize: failed to open checkpoint store",
			slog.String("error", err.Error()),
		)
		return 1 // Count as error - all checkpoints will be skipped
	}
	store := stores.Persistent

	precomputed := precomputeTranscriptBlobsForFinalize(logCtx, repo, redactedTranscript, state)

	updateOpts := checkpoint.UpdateOptions{
		SessionID:               state.SessionID,
		Transcript:              redactedTranscript,
		Assets:                  finalizeAssets,
		PreserveAssetsWhenEmpty: sidecarCapable || !externalizationRan,
		Prompts:                 prompts,
		Agent:                   state.AgentType,
		SkillEvents:             skillEvents,

	// Retire the subagent's own session the same way an ordinary turn-end does,
	// so its phase and pre-prompt state do not linger as an active session.
	transitionSessionTurnEnd(ctx, step.sessionID, step.event)
	if cleanupErr := CleanupPrePromptState(ctx, step.sessionID); cleanupErr != nil {
		logging.Warn(logCtx, "failed to cleanup pre-prompt state",
			slog.String("error", cleanupErr.Error()))
	}
	return nil
}

// --- Helper functions ---

// turnHasMidTurnCheckpoints reports whether a commit during this turn already
// condensed the session (TurnCheckpointIDs). That condensation consumed and
// released prompt.txt, and turn-end finalization rewrites those checkpoints'
// prompts from prompt.txt, so backfilling it with prompts recorded after the
// commit would replace the committed checkpoint's prompts with later ones. The
// next condensation extracts those later prompts from the transcript itself.
func turnHasMidTurnCheckpoints(ctx context.Context, sessionID string) bool {
	state, err := strategy.LoadSessionState(ctx, sessionID)
	if err != nil || state == nil {
		return false
	}
	return len(state.TurnCheckpointIDs) > 0
}

// resolveTranscriptOffset determines the transcript offset to use for parsing.
// Prefers pre-prompt state, falls back to session state.
func resolveTranscriptOffset(ctx context.Context, preState *PrePromptState, sessionID string) int {
	logCtx := logging.WithComponent(ctx, "lifecycle")
	if preState != nil && preState.TranscriptOffset > 0 {
		logging.Debug(logCtx, "pre-prompt state found, parsing transcript from offset",
			slog.Int("offset", preState.TranscriptOffset))
		return preState.TranscriptOffset
	}

	// Fall back to session state
	sessionState, loadErr := strategy.LoadSessionState(ctx, sessionID)
	if loadErr != nil {
		logging.Warn(logCtx, "failed to load session state",
			slog.String("error", loadErr.Error()))
		return 0
	}
	if sessionState != nil && sessionState.CheckpointTranscriptStart > 0 {
		logging.Debug(logCtx, "session state found, parsing transcript from offset",
			slog.Int("offset", sessionState.CheckpointTranscriptStart))
		return sessionState.CheckpointTranscriptStart
	}

	return 0
}

// recordCaptureDegraded persists (or clears) the capture-degraded timestamp on
// session state at turn end, so a status-budget breach is visible in
// `entire status` instead of only in .entire/logs. A healthy turn clears it —
// the marker means "the LAST turn degraded", not "some turn once did". Skips
// the state write when nothing changes, which is the common case.
func recordCaptureDegraded(ctx context.Context, sessionID string, degraded bool) {
	mutErr := strategy.MutateSessionState(ctx, sessionID, func(state *strategy.SessionState) error {
		if !degraded && state.CaptureDegradedAt == nil {
			return strategy.ErrMutationSkip
		}
		state.CaptureDegradedAt = nil
		if degraded {
			now := time.Now().UTC()
			state.CaptureDegradedAt = &now
		}
		return nil
	})
	if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
		logging.Warn(logging.WithComponent(ctx, "lifecycle"), "failed to record capture degradation in session state",
			slog.String("error", mutErr.Error()))
	}
}

// transitionSessionTurnEnd transitions the session phase to IDLE and dispatches turn-end actions.
func transitionSessionTurnEnd(ctx context.Context, sessionID string, event *agent.Event) {
	logCtx := logging.WithComponent(ctx, "lifecycle")
	var appendedSkillEvents []agent.SkillEvent
	mutErr := strategy.MutateSessionStateOnSaved(ctx, sessionID, func(state *strategy.SessionState) error {
		appendedSkillEvents = persistEventMetadataToState(event, state)
		if err := strategy.TransitionAndLog(ctx, state, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); err != nil {
			logging.Warn(logCtx, "turn-end transition failed",
				slog.String("error", err.Error()))
		}
		// HandleTurnEnd mutates state in-place; the outer MutateSessionState
		// save flushes those changes. Any reentrant MutateSessionState calls
		// it makes on this session ID share this state pointer via the gate —
		// and any post-save effect they register is flushed by this frame.
		strat := GetStrategy(ctx)
		// The turn-end finalize extracts skill events from the full transcript
		// and appends the new ones to state.SkillEvents — snapshot its growth
		// so those events reach telemetry alongside the hook-provided ones.
		skillEventsBefore := len(state.SkillEvents)
		if err := strat.HandleTurnEnd(ctx, state, turnEndFinalizeDeadline(state.AgentType)); err != nil {
			logging.Warn(logCtx, "turn-end action dispatch failed",
				slog.String("error", err.Error()))
		}
		// Guarded rather than sliced blind: nothing shortens SkillEvents today,
		// but a future path that rewrote or trimmed the list would turn this
		// into a panic in a hook.
		if len(state.SkillEvents) > skillEventsBefore {
			appendedSkillEvents = append(appendedSkillEvents, state.SkillEvents[skillEventsBefore:]...)
		}
		return nil
	}, func() {
		strategy.EmitSkillInvocationTelemetry(ctx, appendedSkillEvents)
	})
	if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
		logging.Warn(logCtx, "failed to update session phase on turn end",
			slog.String("error", mutErr.Error()))
	}
}

// sessionEndedAt resolves the EndedAt stamp for a session being finalized under
// the given policy. endedWhenLastSeen falls back through the state's own record
// of activity and never yields a zero time: an unknown last-seen is stamped now,
// which is what the old unconditional behavior did anyway.
func sessionEndedAt(state *strategy.SessionState, when endedAtPolicy) time.Time {
	if when == endedWhenLastSeen {
		if state.LastInteractionTime != nil && !state.LastInteractionTime.IsZero() {
			return *state.LastInteractionTime
		}
		if !state.StartedAt.IsZero() {
			return state.StartedAt
		}
	}
	return time.Now()
}

// endedAtPolicy selects the timestamp written to SessionState.EndedAt.
type endedAtPolicy int

const (
	// endedNow stamps the current time: the session is ending as we watch it,
	// driven by its own session-end hook or by `entire session stop`.
	endedNow endedAtPolicy = iota

	// endedWhenLastSeen stamps the session's last known activity instead, for
	// finalizations that discover an end that already happened. The exited-owner
	// sweep is the case: the agent quit at some unknown earlier point, and since

			}
		}
	}
}

// Compute subagents directory for agents that support subagent extraction.
subagentsDir := paths.SubagentsDir(filepath.Dir(transcriptRef), event.SessionID)

// Extract metadata via agent interface (modified files)
var modifiedFiles []string

if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
	// Extract modified files - prefer SubagentAwareExtractor if available to include subagent files
	if subagentExtractor, subOk := agent.AsSubagentAwareExtractor(ag); subOk {
		if files, fileErr := subagentExtractor.ExtractAllModifiedFiles(transcriptData, transcriptOffset, subagentsDir); fileErr != nil {
			logging.Warn(logCtx, "failed to extract modified files (with subagents)",
				slog.String("error", fileErr.Error()))
		} else {
			modifiedFiles = files
		}
	} else {
		// Fall back to basic extraction (main transcript only)
		if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(logCtx, transcriptRef, transcriptOffset); fileErr != nil {
			logging.Warn(logCtx, "failed to extract modified files",
				slog.String("error", fileErr.Error()))
		} else {
			modifiedFiles = files
		}
	}
}
extractSpan.End()

// Generate commit message from last prompt (read from session state, set at TurnStart).
// In exec mode, session state LastPrompt may be empty because UserPromptSubmit never fires.
// Fall back to backfilledPrompt extracted from the transcript.
// Single load serves both prompt retrieval and backfill.
_, commitMsgSpan := perf.Start(ctx, "generate_commit_message")
lastPrompt := ""
sessionState, stateErr := strategy.LoadSessionState(ctx, sessionID)
if stateErr == nil && sessionState != nil {
	lastPrompt = sessionState.LastPrompt
}
// Backfill LastPrompt so `entire status` shows the prompt even when no
// files were modified (before the early return below).
if lastPrompt == "" && backfilledPrompt != "" {
	lastPrompt = backfilledPrompt
	mutErr := strategy.MutateSessionState(ctx, sessionID, func(state *strategy.SessionState) error {
		if state.LastPrompt != "" {
			return strategy.ErrMutationSkip
		}
		state.LastPrompt = backfilledPrompt
		return nil
	})
	if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
		logging.Warn(logCtx, "failed to backfill LastPrompt in session state",
			slog.String("error", mutErr.Error()))
	}
}
commitMessage := generateCommitMessage(lastPrompt, ag.Type())
logging.Debug(logCtx, "using commit message",
	slog.Int("message_length", len(commitMessage)))
commitMsgSpan.End()

// Get worktree root for path normalization
_, detectSpan := perf.Start(ctx, "detect_file_changes")
repoRoot, err := paths.WorktreeRoot(ctx)
if err != nil {
	detectSpan.RecordError(err)
	detectSpan.End()
	return fmt.Errorf("failed to get worktree root: %w", err)
}

var preUntrackedFiles []string
if preState != nil {
	logging.Debug(logCtx, "pre-prompt state",
		slog.Int("pre_existing_untracked_files", len(preState.UntrackedFiles)))
	preUntrackedFiles = preState.PreUntrackedFiles()
}

// Detect file changes via git status. captureDegraded tracks whether any
// status scan feeding this turn breached its budget, so the marker
// persisted at turn end reflects the whole turn, not just this walk.
captureDegraded := preState != nil && preState.UntrackedScanSkipped
changes, err := DetectFileChanges(ctx, preUntrackedFiles)
if err != nil {
	captureDegraded = captureDegraded || errors.Is(err, gitrepo.ErrStatusBudgetExceeded)
	logStatusDegrade(logCtx, "failed to compute file changes", err)
}
if changes != nil && preState != nil && preState.UntrackedScanSkipped {
	// The turn-start untracked scan was skipped (e.g. status-walk budget
	// breach), so there is no baseline: every untracked file in the
	// worktree would be misreported as created by this turn.
	logging.Warn(logCtx, "skipping new-file detection: pre-prompt untracked scan was skipped")
	changes.New = nil
}
detectSpan.End()

// Filter and normalize all paths
_, normalizeSpan := perf.Start(ctx, "filter_and_normalize_paths")
relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
var relNewFiles, relDeletedFiles []string
if changes != nil {
	relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
	relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)

	// Merge git-status modified files as a fallback for transcript parsing.
	// Transcript parsing is the primary source for modified files, but it can miss
	// files if the agent uses an unrecognized tool or the transcript format changes.
	// Git status catches any tracked file with working-tree changes.
	relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
}
// Pre-existing untracked files the turn changed: git status lists them as
// untracked both before and after, so neither New nor Modified carries
// them, and a shell edit leaves no trace in the transcript.
relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(preState.ChangedUntrackedFiles(repoRoot), repoRoot))

// Filter detected changes to exclude state already committed to HEAD.
// When an agent commits files mid-turn, those changes are condensed by
// PostCommit and must not be re-checkpointed by SaveStep — otherwise a
// Stop right after the commit produces an empty duplicate checkpoint
// (observed with Antigravity, whose Stop fires after its own git commit).
// A file is "committed" if it exists in HEAD with the same content as the
// working tree. Only relModifiedFiles needs this: it merges
// transcript-extracted files, which can include already-committed ones.
// relNewFiles (untracked ⇒ never in HEAD) and relDeletedFiles (git status
// cannot report a committed deletion) are uncommitted by construction —
// filtering them against HEAD would wrongly drop deletions of files
// created-then-deleted within the session (absent from HEAD) from the
// session's record.
relModifiedFiles = filterToUncommittedFiles(ctx, relModifiedFiles, repoRoot)
// Drop paths no commit can carry (see strategy.FilterTrackableChanges).
relModifiedFiles, relNewFiles, relDeletedFiles = strategy.FilterTrackableChanges(ctx, repoRoot, relModifiedFiles, relNewFiles, relDeletedFiles)
normalizeSpan.End()

// Codex owns an authoritative child ledger. Refresh it before the
// no-files gate: a read-only child can finish without producing a turn-end
// step, but its exact availability still must replace stale coverage.
var codexInventoryUsage *agent.TokenUsage
var codexLedgerVersion *uint64
if ag.Type() == agent.AgentTypeCodex {
	inventoryOffset := 0
	if preState != nil {
		inventoryOffset = preState.TranscriptOffset
	}
	codexInventoryUsage, codexLedgerVersion = refreshCodexInventory(ctx, ag, sessionID, transcriptData, inventoryOffset)
}

// Check if there are any changes
